// ============================================================
// DATA LOADING — reads from viz_data.json generated by Python pipeline
// ============================================================

const FALLBACK_DATA = { matches: [], tropeDistribution: [], timeline: [], calibration: { echoScores: [], legitimateScores: [] }, legitimateExamples: [], metadata: { thresholds: { high: 0.85, medium: 0.70, low: 0.55 }, tropeNames: {}, tropeColors: {} } };

function useVizData() {
  const [data, setData] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    fetch("/viz_data.json")
      .then(r => { if (!r.ok) throw new Error(`${r.status}`); return r.json(); })
      .then(d => { setData(d); setLoading(false); })
      .catch(e => {
        console.warn("viz_data.json not found, using sample data. Run: python generate_viz_data.py --generate");
        setData(null);
        setLoading(false);
        setError(e.message);
      });
  }, []);

  return { data, loading, error };
}

