function TimelineView({ timeline }) {
  return (
    <div style={{ position: "relative", padding: "20px 0" }}>
      <div style={{ position: "absolute", left: "50%", top: 0, bottom: 0, width: 2, background: "linear-gradient(to bottom, #c0392b, #666, #3498db)" }} />
      {timeline.map((evt, i) => {
        const isLeft = evt.type === "soviet" || evt.type === "transition";
        const color = evt.type === "soviet" ? "#c0392b" : evt.type === "transition" ? "#f1c40f" : "#3498db";
        return (
          <div key={i} style={{ display: "flex", alignItems: "center", marginBottom: 12, flexDirection: isLeft ? "row" : "row-reverse" }}>
            <div style={{ flex: 1, textAlign: isLeft ? "right" : "left", paddingRight: isLeft ? 24 : 0, paddingLeft: isLeft ? 0 : 24 }}>
              <span style={{ fontSize: 12, fontWeight: 700, color }}>{evt.year}</span>
              <span style={{ fontSize: 12, color: "var(--text-secondary)", marginLeft: 8 }}>{evt.label}</span>
            </div>
            <div style={{ width: 12, height: 12, borderRadius: "50%", background: color, border: "2px solid var(--bg-card)", zIndex: 1, flexShrink: 0 }} />
            <div style={{ flex: 1 }} />
          </div>
        );
      })}
    </div>
  );
}

function TropeChart({ tropeDistribution }) {
  const chartData = tropeDistribution
    .filter(d => d.sovietCount > 0 || d.modernCount > 0)
    .map(d => ({
      ...d,
      shortLabel: TROPE_SHORT_LABELS[d.id] || d.name,
    }));

  // Show all 9 tropes if available; ensure enough height per bar
  const barHeight = 44;
  const chartHeight = Math.max(300, chartData.length * barHeight + 60);

  const CustomTooltip = ({ active, payload }) => {
    if (!active || !payload?.length) return null;
    return (
      <div style={{ background: "var(--bg-card-alt)", border: "1px solid var(--border)", borderRadius: 8, padding: "10px 14px", fontSize: 12, color: "var(--text-primary)", maxWidth: 280 }}>
        <div style={{ fontWeight: 700, marginBottom: 4, color: "var(--text-heading)" }}>
          {payload[0]?.payload?.name}
        </div>
        <div style={{ display: "flex", justifyContent: "space-between", gap: 16, marginTop: 2 }}>
          <span style={{ color: "#c0392b" }}>Soviet (THEN)</span>
          <span style={{ fontWeight: 700 }}>{payload[0]?.value || 0}</span>
        </div>
        <div style={{ display: "flex", justifyContent: "space-between", gap: 16, marginTop: 2 }}>
          <span style={{ color: "#3498db" }}>Modern (NOW)</span>
          <span style={{ fontWeight: 700 }}>{payload[1]?.value || 0}</span>
        </div>
      </div>
    );
  };

  return (
    <>
    <ResponsiveContainer width="100%" height={chartHeight}>
      <BarChart data={chartData} layout="vertical" margin={{ left: 10, right: 20, top: 10, bottom: 10 }}>
        <XAxis type="number" tick={{ fill: "var(--text-secondary)", fontSize: 11 }} allowDecimals={false} />
        <YAxis type="category" dataKey="shortLabel" width={120} tick={{ fill: "var(--text-primary)", fontSize: 12, fontWeight: 500 }} />
        <Tooltip content={<CustomTooltip />} />
        <Bar dataKey="sovietCount" name="Soviet (THEN)" fill="#c0392b" radius={[0, 4, 4, 0]} barSize={14} />
        <Bar dataKey="modernCount" name="Modern (NOW)" fill="#3498db" radius={[0, 4, 4, 0]} barSize={14} />
      </BarChart>
    </ResponsiveContainer>
    <div style={{ display: "flex", justifyContent: "center", gap: 24, marginTop: 8, fontSize: 12 }}>
      <span style={{ display: "flex", alignItems: "center", gap: 6 }}>
        <span style={{ width: 12, height: 12, borderRadius: 2, background: "#c0392b", display: "inline-block" }} />
        <span style={{ color: "#c0392b", fontWeight: 600 }}>Soviet (THEN)</span>
      </span>
      <span style={{ display: "flex", alignItems: "center", gap: 6 }}>
        <span style={{ width: 12, height: 12, borderRadius: 2, background: "#3498db", display: "inline-block" }} />
        <span style={{ color: "#3498db", fontWeight: 600 }}>Modern (NOW)</span>
      </span>
    </div>
    </>
  );
}

function TropeDescriptionTable({ tropeNames }) {
  const allTropes = Object.keys(TROPE_DESCRIPTIONS);
  return (
    <div style={{ marginTop: 28 }}>
      <div style={{ fontSize: 13, fontWeight: 700, color: "var(--text-primary)", marginBottom: 12, letterSpacing: 1, textTransform: "uppercase" }}>
        Trope Taxonomy
      </div>
      <div style={{ display: "grid", gap: 8 }}>
        {allTropes.map(id => (
          <div key={id} style={{
            display: "flex", gap: 12, alignItems: "flex-start",
            padding: "8px 12px", background: "var(--bg-card)", borderRadius: 8,
            borderLeft: "3px solid var(--text-muted)",
          }}>
            <div style={{ minWidth: 130 }}>
              <span style={{ fontSize: 11, fontWeight: 700, color: "var(--text-primary)" }}>
                {TROPE_SHORT_LABELS[id] || id}
              </span>
            </div>
            <div style={{ fontSize: 11, color: "var(--text-secondary)", lineHeight: 1.5 }}>
              <span style={{ color: "var(--text-primary)", fontWeight: 600 }}>{tropeNames[id] || id}</span>
              {" — "}{TROPE_DESCRIPTIONS[id]}
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}

function CalibrationView({ calibration }) {
  const allScores = [
    ...calibration.echoScores.slice(0, 8),
    ...calibration.legitimateScores,
  ].sort((a, b) => b.score - a.score);

  return (
    <div>
      <div style={{ display: "flex", gap: 4, marginBottom: 12, flexWrap: "wrap" }}>
        {[{ label: "HIGH ≥0.85", color: "#2ecc71" }, { label: "MEDIUM ≥0.70", color: "#f1c40f" }, { label: "LOW ≥0.55", color: "#e67e22" }, { label: "NO MATCH <0.55", color: "#555" }].map(t => (
          <span key={t.label} style={{ fontSize: 10, color: t.color, fontWeight: 600, padding: "2px 6px", border: `1px solid ${t.color}33`, borderRadius: 4 }}>{t.label}</span>
        ))}
      </div>
      {allScores.map((item, i) => {
        const color = item.score >= 0.85 ? "#2ecc71" : item.score >= 0.70 ? "#f1c40f" : item.score >= 0.55 ? "#e67e22" : "#555";
        const isLegit = item.type === "legitimate";
        return (
          <div key={i} style={{ display: "flex", alignItems: "center", gap: 12, marginBottom: 6 }}>
            <span style={{ fontSize: 11, color: isLegit ? "#2ecc71" : "var(--text-primary)", minWidth: 150, textAlign: "right", fontWeight: isLegit ? 700 : 400 }}>
              {isLegit ? "✓ " : ""}{item.label}
            </span>
            <div style={{ flex: 1, height: 8, background: "var(--bg-card-alt)", borderRadius: 4, overflow: "hidden" }}>
              <div style={{ width: `${item.score * 100}%`, height: "100%", background: isLegit ? "#27ae6055" : color, borderRadius: 4 }} />
            </div>
            <span style={{ fontSize: 12, fontWeight: 700, color, minWidth: 36, textAlign: "right" }}>{Math.round(item.score * 100)}%</span>
          </div>
        );
      })}
      <div style={{ fontSize: 11, color: "#27ae60", marginTop: 16, fontStyle: "italic" }}>
        ✓ Legitimate criticism correctly scores well below threshold — no false positives
      </div>
    </div>
  );
}

function SocialCard({ match, tropeNames, tropeColors }) {
  return (
    <div style={{ background: "var(--bg-page)", border: "1px solid var(--border)", borderRadius: 16, padding: 24, maxWidth: 500, margin: "0 auto" }}>
      <div style={{ fontSize: 10, letterSpacing: 3, color: "var(--text-secondary)", textTransform: "uppercase", textAlign: "center", marginBottom: 20 }}>#IveSeenThisBefore</div>
      <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 20 }}>
        <div>
          <div style={{ fontSize: 10, fontWeight: 700, color: "#c0392b", letterSpacing: 2, marginBottom: 8 }}>THEN — {match.sovietYear}</div>
          <div style={{ fontSize: 14, color: "var(--text-primary)", fontStyle: "italic", lineHeight: 1.5, borderLeft: "2px solid #c0392b", paddingLeft: 12 }}>"{match.sovietText}"</div>
          <div style={{ fontSize: 10, color: "var(--text-source)", marginTop: 8 }}>{match.sovietSource}</div>
        </div>
        <div>
          <div style={{ fontSize: 10, fontWeight: 700, color: "#3498db", letterSpacing: 2, marginBottom: 8 }}>NOW — {match.modernYear}</div>
          <div style={{ fontSize: 14, color: "var(--text-primary)", fontStyle: "italic", lineHeight: 1.5, borderLeft: "2px solid #3498db", paddingLeft: 12 }}>"{match.modernText}"</div>
          <div style={{ fontSize: 10, color: "var(--text-source)", marginTop: 8 }}>{match.modernSource}</div>
        </div>
      </div>
      {match.echo_explanation && (
        <div style={{ fontSize: 12, color: "var(--text-secondary)", fontStyle: "italic", textAlign: "center", marginTop: 16, padding: "0 12px" }}>
          {match.echo_explanation}
        </div>
      )}
      <div style={{ display: "flex", gap: 6, justifyContent: "center", marginTop: 12, flexWrap: "wrap" }}>
        {match.tropes.map(t => <TropeBadge key={t} trope={t} tropeNames={tropeNames} tropeColors={tropeColors} />)}
      </div>
    </div>
  );
}

// ============================================================
// MAIN APP
// ============================================================

const TABS = ["Matches", "Analyzer", "Timeline", "Tropes", "Calibration", "Social Cards"];

export default function App() {
  const { matches, tropeDistribution, timeline, calibration, tropeNames, tropeColors, isLive, loading, model, generatedAt, sovietCorpusSize, modernCorpusSize } = useResolvedData();
  const [activeTab, setActiveTab] = useState(0);
  const [selectedCard, setSelectedCard] = useState(0);

  if (loading) {
    return (
      <div style={{ minHeight: "100vh", background: "var(--bg-page)", color: "var(--text-secondary)", fontFamily: "'Courier New', 'Consolas', monospace", display: "flex", alignItems: "center", justifyContent: "center" }}>
        <div style={{ textAlign: "center" }}>
          <div style={{ fontSize: 24, marginBottom: 12, color: "#c0392b" }}>Loading...</div>
          <div style={{ fontSize: 12, color: "var(--text-muted)" }}>Fetching visualization data</div>
        </div>
      </div>
    );
  }

  return (
    <div style={{ minHeight: "100vh", background: "var(--bg-page)", color: "var(--text-primary)", fontFamily: "'Courier New', 'Consolas', monospace", padding: "32px 24px" }}>
      <style>{`
        @keyframes fadeSlideIn { from { opacity: 0; transform: translateY(16px); } to { opacity: 1; transform: translateY(0); } }
      `}</style>
      <div style={{ maxWidth: 900, margin: "0 auto" }}>
        {/* Header */}
        <div style={{ textAlign: "center", marginBottom: 40 }}>
          <div style={{ fontSize: 11, letterSpacing: 6, color: "#c0392b", textTransform: "uppercase", marginBottom: 8 }}>
            {isLive ? "Live Data" : "Sample Data"}{model ? ` • ${model.split("/").pop()}` : ""}
          </div>
          <div style={{ display: "flex", alignItems: "center", justifyContent: "center", gap: 12 }}>
            <h1 style={{ fontSize: 32, fontWeight: 300, color: "var(--text-heading)", margin: 0, fontFamily: "'Georgia', serif", letterSpacing: 1 }}>
              I've Seen This Before
            </h1>
            <ThemeToggle />
          </div>
          <p style={{ fontSize: 13, color: "var(--text-secondary)", maxWidth: 600, margin: "12px auto 0", lineHeight: 1.6 }}>
            Mapping Soviet anti-Zionist propaganda to its modern echoes using semantic similarity
          </p>
          {!isLive && (
            <div style={{ fontSize: 10, color: "#d35400", marginTop: 8 }}>
              Using sample data. Run <code style={{ background: "var(--bg-card-alt)", padding: "2px 6px", borderRadius: 3 }}>python generate_viz_data.py --generate</code> to use real embeddings.
            </div>
          )}
          {generatedAt && (
            <div style={{ fontSize: 10, color: "var(--text-muted)", marginTop: 4 }}>
              Generated: {new Date(generatedAt).toLocaleString()}
            </div>
          )}
        </div>

        {/* Tabs */}
        <div style={{ display: "flex", gap: 2, marginBottom: 32, borderBottom: "1px solid var(--bg-card-alt)", paddingBottom: 1, overflowX: "auto" }}>
          {TABS.map((tab, i) => (
            <button key={tab} onClick={() => setActiveTab(i)} style={{
              background: activeTab === i ? "var(--bg-card-alt)" : "transparent", border: "none",
              color: activeTab === i ? "var(--text-heading)" : "var(--text-source)", padding: "10px 16px", cursor: "pointer",
              fontSize: 12, fontFamily: "inherit", fontWeight: activeTab === i ? 700 : 400,
              borderRadius: "8px 8px 0 0", whiteSpace: "nowrap",
            }}>
              {tab}{tab === "Analyzer" ? " ⚡" : ""}
            </button>
          ))}
        </div>

        {/* Tab Content */}
        {activeTab === 0 && (
          <div>
            <div style={{ fontSize: 12, color: "var(--text-secondary)", marginBottom: 20, lineHeight: 1.6, maxWidth: 720, background: "var(--bg-card)", padding: "12px 16px", borderRadius: 8, borderLeft: "3px solid var(--text-muted)" }}>
              <strong style={{ color: "var(--text-primary)" }}>About these matches:</strong> Each pair shows a Soviet propaganda passage alongside modern rhetoric that uses strikingly similar framing. These are <em>structural parallels</em> in argumentation — they do not by themselves prove that modern speakers learned these arguments from Soviet sources. Establishing actual transmission pathways requires historical evidence beyond computational analysis. Matches were selected from {matches.length > 0 ? "a larger candidate set" : "automated results"} and reviewed for rhetorical coherence.
            </div>
            <div style={{ display: "flex", flexDirection: "column", gap: 20 }}>
              {matches.map((match, i) => (
                <MatchCard key={match.id || i} match={match} index={i} tropeNames={tropeNames} tropeColors={tropeColors} />
              ))}
            </div>
          </div>
        )}

        {activeTab === 1 && (
          <div style={{ background: "var(--gradient-card)", border: "1px solid var(--border)", borderRadius: 12, padding: 24 }}>
            <LiveAnalyzer tropeNames={tropeNames} tropeColors={tropeColors} />
          </div>
        )}

        {activeTab === 2 && (
          <div style={{ background: "var(--gradient-card)", border: "1px solid var(--border)", borderRadius: 12, padding: 24 }}>
            <div style={{ fontSize: 12, color: "var(--text-secondary)", marginBottom: 16 }}>The pipeline from Soviet propaganda factories to modern campus discourse</div>
            <TimelineView timeline={timeline} />
          </div>
        )}

        {activeTab === 3 && (
          <div style={{ background: "var(--gradient-card)", border: "1px solid var(--border)", borderRadius: 12, padding: 24 }}>
            <div style={{ fontSize: 12, color: "var(--text-secondary)", marginBottom: 16 }}>Which Soviet propaganda tropes appear most frequently in modern discourse</div>
            <TropeChart tropeDistribution={tropeDistribution} />
            <TropeDescriptionTable tropeNames={tropeNames} />
          </div>
        )}

        {activeTab === 4 && (
          <div style={{ background: "var(--gradient-card)", border: "1px solid var(--border)", borderRadius: 12, padding: 24 }}>
            <div style={{ fontSize: 12, color: "var(--text-secondary)", marginBottom: 16 }}>Confidence calibration — legitimate criticism scores well below match threshold</div>
            <CalibrationView calibration={calibration} />
          </div>
        )}

        {activeTab === 5 && (
          <div>
            <div style={{ fontSize: 12, color: "var(--text-secondary)", marginBottom: 16 }}>Shareable cards for the #IveSeenThisBefore campaign</div>
            <div style={{ display: "flex", gap: 8, marginBottom: 20, justifyContent: "center", flexWrap: "wrap" }}>
              {matches.map((_, i) => (
                <button key={i} onClick={() => setSelectedCard(i)} style={{
                  background: selectedCard === i ? "var(--border)" : "transparent",
                  border: `1px solid ${selectedCard === i ? "#3498db" : "var(--border)"}`,
                  color: selectedCard === i ? "var(--text-heading)" : "var(--text-secondary)", padding: "6px 12px",
                  borderRadius: 6, cursor: "pointer", fontSize: 11, fontFamily: "inherit",
                }}>
                  Match {i + 1}
                </button>
              ))}
            </div>
            {matches[selectedCard] && <SocialCard match={matches[selectedCard]} tropeNames={tropeNames} tropeColors={tropeColors} />}
          </div>
        )}

        {/* Dataset Info Bar */}
        <div style={{
          display: "flex", justifyContent: "center", gap: 24, marginTop: 48, padding: "12px 16px",
          background: "var(--bg-card)", border: "1px solid var(--bg-card-alt)", borderRadius: 8, flexWrap: "wrap",
        }}>
          {sovietCorpusSize != null && (
            <span style={{ fontSize: 11, color: "#c0392b" }}>Soviet Corpus: <strong>{sovietCorpusSize}</strong> passages</span>
          )}
          {modernCorpusSize != null && (
            <span style={{ fontSize: 11, color: "#3498db" }}>Modern Corpus: <strong>{modernCorpusSize}</strong> passages</span>
          )}
          <span style={{ fontSize: 11, color: "var(--text-secondary)" }}>Matches: <strong style={{ color: "var(--text-primary)" }}>{matches.length}</strong></span>
          {model && (
            <span style={{ fontSize: 11, color: "var(--text-secondary)" }}>Model: <strong style={{ color: "var(--text-primary)" }}>{model.split("/").pop()}</strong></span>
          )}
        </div>

        {/* Footer */}
        <div style={{ textAlign: "center", marginTop: 16, paddingTop: 24, borderTop: "1px solid var(--bg-card-alt)" }}>
          <div style={{ fontSize: 10, color: "var(--text-muted)", letterSpacing: 2 }}>
            {isLive ? "LIVE DATA FROM ML PIPELINE" : "PROTOTYPE — SAMPLE DATA"} • SIMILARITY SCORES {isLive ? "COMPUTED BY" : "WILL BE COMPUTED BY"} EMBEDDING MODEL
          </div>
        </div>
      </div>
    </div>
  );
}
